parameters.jsCode:
const response = $input.item.json;
const content = response.choices[0].message.content;
const webhookData = $('Keep User Details').first().json;
// This line is correct, it gets the 3 description lines
const descriptions = content.split('\n').filter(line => line.trim().startsWith('*')).slice(0, 3);
const propertyData = $('Parse Property Data').first().json;

const imageData = propertyData.images.map((imageUrl, index) => {
  let desc = descriptions[index] || 'Beautiful property feature';

  // NEW: Strip the prefix (e.g., "* **Description 1:** ") and any quotes
  // This cleans the prompt for the video model
  desc = desc.replace(/^[*\s]*Description\s\d:[\s"']*/, '').replace(/["']$/, '');

  return {
    imageUrl,
    description: desc,
    index
  };
});

return imageData.map(item => ({
  ...propertyData,
  currentImage: item.imageUrl,
  currentDescription: item.description, // This will now be clean
  imageIndex: item.index,
  name: webhookData.name,
  email: webhookData.email
}));

const MAX_RETRIES = 20;
const retryCount = $json.retryCount || 0;

if (retryCount >= MAX_RETRIES) {
  throw new Error(`Timeout after ${MAX_RETRIES} retries (15 minutes)`);
}

return {
  taskId: $json.taskId,
  description: $json.description,
  imageUrl: $json.imageUrl,
  address: $json.address,
  price: $json.price,
  beds: $json.beds,
  baths: $json.baths,
  sqft: $json.sqft,
  name: $json.name,
  email: $json.email,
  retryCount: retryCount + 1,
  status: $json.status
};

